    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
    pub enum Resource {
        TaskSlot,
    }
    #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
    pub enum Invariant {
        I0,
        I1,
        I2,
    }
    pub const fn invariant_id(invariant: Invariant) -> u64 {
        match invariant {
            Invariant::I0 => 9928732756331203286,
            Invariant::I1 => 18008285519746033831,
            Invariant::I2 => 15118058188914431676,
        }
    }
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub struct InvariantViolation {
        pub invariant: Invariant,
    }
    pub fn check_invariants(
        state: State,
        resource: impl Fn(Resource) -> i64,
    ) -> Result<(), InvariantViolation> {
        let _ = &resource;
        let terminal = matches!(
            state, State::Completed | State::Cancelled | State::Trapped
        );
        let _ = state;
        let _ = terminal;
        if resource(Resource::TaskSlot) < 0 {
            return Err(InvariantViolation {
                invariant: Invariant::I0,
            });
        }
        if terminal && resource(Resource::TaskSlot) != 0 {
            return Err(InvariantViolation {
                invariant: Invariant::I1,
            });
        }
        if state == State::Running && resource(Resource::TaskSlot) < 1 {
            return Err(InvariantViolation {
                invariant: Invariant::I2,
            });
        }
        Ok(())
    }
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub struct ResourceDelta {
        pub resource: &'static str,
        pub amount: i64,
    }
    pub struct Outcome {
        pub state: State,
        pub transition_id: u64,
        pub deltas: &'static [ResourceDelta],
    }
    #[derive(Clone, Copy, Debug, PartialEq, Eq)]
    pub enum TransitionError {
        GuardRejected { guard: Guard, transition_id: u64 },
        Undefined { state: State, event: Event },
    }
    impl std::fmt::Display for TransitionError {
        fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            match self {
                Self::GuardRejected { guard, .. } => {
                    write!(formatter, "guard `{guard:?}` rejected transition")
                }
                Self::Undefined { state, event } => {
                    write!(
                        formatter, "transition is not defined for {state:?} + {event:?}"
                    )?;
                    Ok(())
                }
            }
        }
    }
    impl std::error::Error for TransitionError {}
